        (3, '2 – Oceans and Continents', 8.0, 'NotoSans-SemiBold', True, 2301728, 529.5, 580.4, 541.2, 684.6),
        (3, 'The Distribution of Water and', 17.0, 'NotoSerif-ExtraBold', True, 36940, 67.8, 67.7, 341.4, 92.6),
