        (3, 'that you can make out?', 12.0, 'NotoSerif-Regular', False, 2301728, 80.8, 268.6, 215.0, 285.9),
        (3, 'In the course of history, India has been called by many', 13.0, 'NotoSerif-Regular', False, 2301728, 67.8, 299.1, 438.4, 317.8),
        (3, 'names — both by its inhabitants and by visitors from outside.', 13.0, 'NotoSerif-Regular', False, 2301728, 67.8, 316.7, 438.4, 335.8),
