        (2, 'What implications did they have?', 11.5, 'TT274T00', False, 2301728, 34.3, 163.9, 174.5, 175.4),
        (2, 'First of all, the war created a new economic and political situation.', 11.5, 'TT274T00', False, 2301728, 34.3, 187.1, 318.3, 198.6),
