        (206, 'diagonal units.', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 204.4, 163.0, 221.3),
        (206, 'Perimeter of a regular polygon', 14.0, 'NotoSerif-Bold', True, 4232106, 71.4, 360.7, 294.2, 381.0),
        (206, 'Like squares, closed figures that have all sides and all angles equal', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 380.9, 501.4, 397.8),
        (206, 'are called regular polygons. We studied the sequence of regular', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 398.7, 501.3, 417.6),
        (206, 'polygons as ‘Shape Sequence’ #1 in Chapter 1. Examples of regular', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 417.0, 501.3, 433.8),
        (206, 'polygons are the equilateral triangle (where all three sides and all', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 435.0, 501.3, 451.8),
        (206, 'three angles are equal), regular pentagon (where all five sides and', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 453.0, 501.4, 469.8),
        (206, 'all five angles are equal), etc.', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 471.0, 254.1, 487.8),
        (206, 'Perimeter of an equilateral triangle', 13.0, 'NotoSerif-Bold', True, 2301728, 71.4, 493.7, 311.4, 512.6),
        (206, 'We know that for any triangle its perimeter', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 514.0, 357.2, 530.8),
        (206, 'is sum of all three sides.', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 532.0, 225.9, 548.8),
        (206, 'Using this understanding, we can find the', 13.0, 'NotoSerif-Regular', False, 2301728, 89.4, 551.0, 357.2, 567.8),
        (206, 'perimeter of an equilateral triangle.', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 569.0, 302.3, 585.9),
        (206, 'Perimeter of an equilateral triangle', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 588.0, 302.4, 604.9),
        (206, '= AB + BC + AC = AB + AB + AB', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 606.0, 259.8, 622.9),
        (206, '= 3 times length of one side.', 13.0, 'NotoSerif-Regular', False, 2301728, 71.4, 625.0, 249.6, 641.9),
