        (208, 'Teacher’s Note', 13.0, 'NotoSerif-Bold', True, 2301728, 244.1, 274.0, 346.2, 292.9),
        (208, 'Help students in recalling the method of finding the area of a', 12.0, 'NotoSerif-Regular', False, 2301728, 99.1, 295.4, 473.7, 311.0),
        (208, 'rectangle and a square using grid papers. Provide square grid', 12.0, 'NotoSerif-Regular', False, 2301728, 99.1, 312.4, 473.7, 328.0),
        (208, 'papers to students and let them come up with the formula.', 12.0, 'NotoSerif-Regular', False, 2301728, 99.1, 329.4, 440.7, 345.0),
        (208, 'Let’s see some real-life problems related to these ideas.', 13.0, 'NotoSerif-Regular', False, 2301728, 89.4, 359.7, 435.5, 376.5),
        (208, 'Example:', 13.0, 'NotoSerif-Bold', True, 2301728, 71.4, 384.4, 137.6, 403.4),
        (208, 'A floor is 5 m long and 4 m wide. A square carpet of sides 3 m', 12.0, 'NotoSerif-Regular', False, 2301728, 137.9, 385.7, 501.1, 401.3),
        (208, 'is laid on the floor. Find the area of the floor that is not carpeted.', 12.0, 'NotoSerif-Regular', False, 2301728, 71.4, 402.7, 448.7, 418.3),
        (208, 'Solution', 13.0, 'NotoSerif-Italic', False, 2301728, 71.4, 424.2, 122.6, 442.9),
        (208, 'Length of the floor = 5 m.', 12.0, 'NotoSerif-Regular', False, 2301728, 73.4, 444.2, 219.9, 459.8),
        (208, 'Width of the floor = 4 m.', 12.0, 'NotoSerif-Regular', False, 2301728, 73.4, 464.2, 215.4, 479.8),
        (208, 'Area of the floor = length × width = 5 m × 4 m = 20 sq m.', 12.0, 'NotoSerif-Regular', False, 2301728, 73.4, 484.2, 397.3, 499.8),
        (208, 'Length of the square carpet = 3 m.', 12.0, 'NotoSerif-Regular', False, 2301728, 73.4, 504.2, 272.1, 519.8),
        (208, 'Area of the carpet = length × length = 3 m × 3 m = 9 sq m.', 12.0, 'NotoSerif-Regular', False, 2301728, 73.4, 524.2, 402.3, 539.8),
        (208, 'Hence, the area of the floor laid with carpet is 9 sq m.', 12.0, 'NotoSerif-Regular', False, 2301728, 73.4, 544.2, 384.5, 559.8),
        (208, 'Therefore, the area of the floor that is not carpeted is: area of the floor', 12.0, 'NotoSerif-Regular', False, 2301728, 89.4, 564.2, 501.1, 579.8),
        (208, 'minus the area of the floor laid with carpet = 20 sq m – 9 sq m = 11 sq m.', 12.0, 'NotoSerif-Regular', False, 2301728, 71.4, 582.2, 491.8, 597.8),
        (208, 'Example:', 13.0, 'NotoSerif-Bold', True, 2301728, 71.4, 606.0, 134.1, 624.9),
