        (1, '5', 60.0, 'AcuminVariableConcept', False, 16777215, 69.0, 46.9, 103.2, 124.7),
        (1, '5.1 Of Questions and Statements', 16.0, 'NotoSerif-Bold', True, 1587802, 93.1, 232.0, 357.8, 253.5),
        (2, 'Ganita Prakash | Grade 7 | Part-II', 10.0, 'NotoSerif-Italic', False, 2301728, 93.1, 38.6, 254.4, 53.0),
        (2, 'We call these statistical statements. Simply put, a statistical statement', 12.0, 'NotoSerif-Regular', False, 2301728, 107.5, 68.8, 504.2, 86.0),
        (2, 'is a claim or summary about some phenomenon, expressed in terms of', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 83.8, 504.3, 101.0),
        (2, 'numerical values, proportions, probabilities, or predictions.', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 98.8, 434.6, 116.0),
        (2, 'A statistical question is a question that can be answered by collecting', 12.0, 'NotoSerif-Regular', False, 2301728, 107.5, 113.8, 504.2, 131.0),
        (2, 'data. For example, “How tall are Grade 7 students in our school?” is a', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 128.8, 504.2, 146.0),
        (2, 'statistical question. We expect that not all Grade 7 students have the same', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 143.8, 504.2, 161.0),
        (2, 'height, but we can collect data, analyse it, and make conclusions about', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 158.8, 504.2, 176.0),
        (2, 'the heights that do occur. The question “Typically, are onions costlier', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 173.8, 504.3, 191.0),
        (2, 'in Yahapur or Wahapur?” is also a statistical question. Prices can vary', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 188.8, 504.2, 206.0),
        (2, 'over time. Therefore, answering this question requires us to look at data,', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 203.8, 504.2, 221.0),
        (2, 'analyse it, and come to conclusions making suitable statistical statements.', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 218.8, 501.2, 236.0),
        (2, 'Which of the following are statistical questions?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 242.8, 373.1, 260.0),
        (2, '(a) What is the price of a tennis ball in India?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 266.3, 357.5, 283.5),
        (2, '(b) How old are the dogs that live on this street?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 285.8, 372.8, 303.0),
        (2, '(c) What fraction of the students in your class like walking up a hill?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 305.3, 489.7, 322.5),
        (2, '(d) Do you like reading?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 324.8, 236.1, 342.0),
        (2, '(e) Approximately how many bricks are in this wall?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 344.3, 400.9, 361.5),
