        (2, '(g) What was the rainfall pattern in Barmer last year?', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 383.3, 407.4, 400.5),
        (2, 'The term statistics refers to the study of collecting, organising,', 12.0, 'NotoSerif-Regular', False, 2301728, 107.5, 402.8, 504.2, 420.0),
        (2, 'analysing, interpreting, and presenting data. In this chapter, we shall', 12.0, 'NotoSerif-Regular', False, 2301728, 93.1, 417.8, 504.3, 435.0),
